#include "ai_settings_capabilities.hpp"
#include "ai_settings_model.hpp"
#include <QRegularExpression>
#include <QDateTime>
namespace aiSettings {
QString capabilityName(const QString& id){static const QMap<QString,QString> names{{"local-factor-v1","本地选股因子"},{"local-factor-lab-v1","本地因子研究"},{"local-ma-strategy-lab-v1","均线策略研究"},{"evidence-orchestrator-v1","证据研究编排"},{"local-paper-portfolio-v1","模拟投资组合"},{"knowledge-fts-v1","资料全文检索"},{"chatgpt-handoff","ChatGPT 手动交接"},{"openai-direct","直接 AI 接口"},{"qlib-lightgbm","Qlib / LightGBM"},{"qlib-master","Qlib / MASTER"},{"alphaagent","AlphaAgent"},{"rd-agent-q","RD-Agent-Q"},{"tradingagents","TradingAgents"},{"finrl-x","FinRL-X"}};return names.value(id,id);}
void validateReports(const QJsonArray& input){require(input.size()<=100,"能力记录过多");for(auto v:input){auto o=v.toObject();QStringList keys{"id","status","claimedStatus","source","sourceObservedAt","checkedAt","importedAt"};for(auto key:o.keys())require(keys.contains(key),"能力证据字段无效");require(o.size()==7&&o.value("status")=="reported-unverified"&&(o.value("source")=="import"||o.value("source")=="host")&&o.value("sourceObservedAt").isNull()&&o.value("checkedAt").isNull(),"能力证据范围无效");require(QRegularExpression("^[a-zA-Z0-9][a-zA-Z0-9._-]{0,80}$").match(o.value("id").toString()).hasMatch()&&!QRegularExpression("(?i)(sk-|bearer|api[_-]?key|password|authorization)").match(o.value("id").toString()).hasMatch(),"能力标识无效");require(QStringList{"available","configured","not_configured","planned","unavailable","validated","hash_verified","metadata_valid","declaration-only","unknown"}.contains(o.value("claimedStatus").toString()),"能力来源状态无效");auto at=o.value("importedAt").toString();require(at.size()<=32&&at.endsWith('Z')&&QDateTime::fromString(at,Qt::ISODateWithMs).isValid(),"能力记录时间无效");}}
QJsonArray declarations(){QJsonArray a;for(const char* id:{"local-factor-v1","local-factor-lab-v1","local-ma-strategy-lab-v1","evidence-orchestrator-v1","local-paper-portfolio-v1","knowledge-fts-v1","chatgpt-handoff","openai-direct","qlib-lightgbm","qlib-master","alphaagent","rd-agent-q","tradingagents","finrl-x"})a.append(QJsonObject{{"id",id},{"status","declaration-only"},{"source","services/modelRegistryService.js"},{"sourceObservedAt",QJsonValue::Null},{"checkedAt",QJsonValue::Null}});return a;}
QJsonArray reported(const QJsonArray& input,const QString& origin){require(input.size()<=100,"能力记录过多");QJsonArray out;for(auto v:input){require(v.isObject(),"能力记录无效");auto o=v.toObject();QString id=o.value("id").toString();require(QRegularExpression("^[a-zA-Z0-9][a-zA-Z0-9._-]{0,80}$").match(id).hasMatch()&&!QRegularExpression("(?i)(sk-|bearer|api[_-]?key|password|authorization)").match(id).hasMatch(),"能力标识无效");QString claimed=o.value("status")=="reported-unverified"?o.value("claimedStatus").toString():o.value("status").toString();if(!QStringList{"available","configured","not_configured","planned","unavailable","validated","hash_verified","metadata_valid","declaration-only"}.contains(claimed))claimed="unknown";out.append(QJsonObject{{"id",id},{"status","reported-unverified"},{"claimedStatus",claimed},{"source",origin},{"sourceObservedAt",QJsonValue::Null},{"checkedAt",QJsonValue::Null},{"importedAt",QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs)}});}return out;}
}
